const body = $input.first().json;
// Vapi sends tool call arguments under message.toolCallList[0].function.arguments
const args = body.message?.toolCallList?.[0]?.function?.arguments || {};
const toolCallId = body.message?.toolCallList?.[0]?.id || '';

const requested_date = args.requested_date || null; // ISO date string or null for 'next available'
const service_type = args.service_type || 'general';
const duration_minutes = args.duration_minutes || 60;

return [{ json: { tool_call_id: toolCallId, requested_date, service_type, duration_minutes } }];

const slots = $input.first().json.slots || [];
const toolCallId = $('Parse Tool Call Args').item.json.tool_call_id;

let slotText = '';
if (slots.length === 0) {
  slotText = 'No availability found in the requested window. Our next opening is typically within 2 business days.';
} else {
  const formatted = slots.map((s, i) => {
    const d = new Date(s.start);
    return `Option ${i + 1}: ${d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })} at ${d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })}`;
  });
  slotText = formatted.join(', or ');
}

// Vapi expects results in this shape
return [{
  json: {
    results: [
      {
        toolCallId: toolCallId,
        result: slotText
      }
    ]
  }
}];
